import React, { useState, useEffect } from 'react';
import { getPatients, getProfessionals, createPatient, updatePatient, deletePatient, searchPatients, createAppointment } from '../services/api';
import './Pages.css';

const formatPhoneInput = (value) => value.replace(/\D/g, '').slice(0, 9);
const formatMedicalNumberInput = (value) => value.replace(/\D/g, '').slice(0, 12);
const formatDate = (dateValue) => {
  if (!dateValue) return '';
  const date = new Date(dateValue);
  return Number.isNaN(date.getTime()) ? dateValue : date.toLocaleDateString('es-CL');
};

const formatDateToInput = (dateStr) => {
  if (!dateStr) return { year: '', month: '', day: '' };
  const parts = String(dateStr).split('-');
  return {
    year: parts[0] || '',
    month: parts[1] || '',
    day: parts[2] || ''
  };
};

const formatInputToDate = (year, month, day) => {
  if (!year || !month || !day) return '';
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

const validatePatientForm = ({ medicalNumber, firstName, lastName, birthDate, phone }) => {
  if (!medicalNumber || !firstName || !lastName || !birthDate || !phone) {
    return 'Todos los campos obligatorios deben estar completos.';
  }
  if (!/^[0-9]{4,12}$/.test(medicalNumber)) {
    return 'Número médico inválido. Debe contener solo dígitos, sin espacios ni letras.';
  }
  if (!/^[0-9]{9}$/.test(phone)) {
    return 'Teléfono inválido. Debe contener exactamente 9 dígitos.';
  }
  return null;
};

export default function Patients() {
  const [patients, setPatients] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [search, setSearch] = useState('');
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({
    medicalNumber: '',
    firstName: '',
    lastName: '',
    birthDate: '',
    birthYear: '',
    birthMonth: '',
    birthDay: '',
    phone: '',
    address: '',
    city: ''
  });
  const [professionals, setProfessionals] = useState([]);
  const [categoryFilter, setCategoryFilter] = useState('medico');
  const [schedulingPatient, setSchedulingPatient] = useState(null);
  const [appointmentForm, setAppointmentForm] = useState({ professionalId: '', appointmentDate: '', appointmentTime: '', reason: '' });
  const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });

  const professionalCategories = [
    { value: 'medico', label: 'Médico' },
    { value: 'kinesiologo', label: 'Kinesiólogo' },
    { value: 'enfermera', label: 'Enfermería' },
    { value: 'quiropractico', label: 'Quiropráctico' }
  ];

  useEffect(() => {
    fetchPatients();
    fetchProfessionals();
  }, []);

  const fetchProfessionals = async () => {
    try {
      const res = await getProfessionals();
      setProfessionals(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error('Error al cargar profesionales:', err.response?.data || err.message);
    }
  };

  const fetchPatients = async () => {
    try {
      const res = await getPatients();
      const normalizedPatients = Array.isArray(res.data)
        ? res.data.map((patient) => ({
            ...patient,
            firstName: patient.firstName || patient.nombre || '',
            lastName: patient.lastName || patient.apellido || '',
            phone: patient.phone || patient.telefono || '',
            city: patient.city || patient.ciudad || ''
          }))
        : [];
      setPatients(normalizedPatients);
      setStatusMessage({ type: '', text: '' });
    } catch (err) {
      console.error('Error al cargar pacientes:', err.response?.data || err.message);
      setStatusMessage({
        type: 'error',
        text: err.response?.data?.mensaje || 'No se pueden cargar los pacientes. Vuelve a iniciar sesión si es necesario.'
      });
    }
  };

  const handleSearch = async () => {
    if (!search) {
      fetchPatients();
      return;
    }
    try {
      const res = await searchPatients(search);
      setPatients(res.data);
      setStatusMessage({ type: '', text: '' });
    } catch (err) {
      console.error('Error buscando pacientes:', err.response?.data || err.message);
      setStatusMessage({
        type: 'error',
        text: err.response?.data?.mensaje || 'No se pudo buscar pacientes.'
      });
    }
  };

  const resetForm = () => {
    setEditing(null);
    setForm({
      medicalNumber: '',
      firstName: '',
      lastName: '',
      birthDate: '',
      birthYear: '',
      birthMonth: '',
      birthDay: '',
      phone: '',
      address: '',
      city: ''
    });
  };

  const startScheduling = (patient) => {
    setSchedulingPatient(patient);
    setAppointmentForm({ professionalId: '', appointmentDate: '', appointmentTime: '', reason: '' });
    setCategoryFilter('medico');
    setStatusMessage({ type: '', text: '' });
  };

  const cancelScheduling = () => {
    setSchedulingPatient(null);
    setAppointmentForm({ professionalId: '', appointmentDate: '', appointmentTime: '', reason: '' });
  };

  const filteredProfessionals = professionals.filter((p) => p.role === categoryFilter);
  const selectedProfessional = professionals.find((p) => p.id === appointmentForm.professionalId);

  const handleAppointmentSubmit = async (e) => {
    e.preventDefault();
    if (!appointmentForm.professionalId || !appointmentForm.appointmentDate || !appointmentForm.appointmentTime || !appointmentForm.reason) {
      setStatusMessage({ type: 'error', text: 'Completa todos los campos de la cita y selecciona un profesional.' });
      return;
    }

    try {
      await createAppointment({
        patientId: schedulingPatient.id,
        professionalId: appointmentForm.professionalId,
        appointmentDate: appointmentForm.appointmentDate,
        appointmentTime: appointmentForm.appointmentTime,
        reason: appointmentForm.reason
      });
      setStatusMessage({ type: 'success', text: 'Cita creada correctamente para el paciente.' });
      cancelScheduling();
    } catch (err) {
      console.error('Error creando cita:', err);
      setStatusMessage({ type: 'error', text: err.response?.data?.mensaje || 'No se pudo crear la cita.' });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Combinar año, mes, día en un solo campo
    const birthDate = formatInputToDate(form.birthYear, form.birthMonth, form.birthDay);
    
    const validationError = validatePatientForm({ 
      medicalNumber: form.medicalNumber,
      firstName: form.firstName,
      lastName: form.lastName,
      birthDate: birthDate,
      phone: form.phone
    });
    if (validationError) {
      setStatusMessage({ type: 'error', text: validationError });
      return;
    }

    try {
      const payload = {
        medicalNumber: form.medicalNumber.trim(),
        firstName: form.firstName.trim(),
        lastName: form.lastName.trim(),
        birthDate: birthDate,
        phone: form.phone.trim(),
        address: form.address.trim(),
        city: form.city.trim(),
        state: form.state?.trim() || '',
        postalCode: form.postalCode?.trim() || ''
      };

      if (editing) {
        await updatePatient(editing, payload);
        setStatusMessage({ type: 'success', text: 'Paciente actualizado correctamente.' });
      } else {
        await createPatient(payload);
        setStatusMessage({ type: 'success', text: 'Paciente creado correctamente.' });
      }

      resetForm();
      setShowForm(false);
      fetchPatients();
      setTimeout(() => setStatusMessage({ type: '', text: '' }), 4000);
    } catch (err) {
      console.error('Error:', err);
      setStatusMessage({
        type: 'error',
        text: err.response?.data?.mensaje || 'Error al guardar paciente. Revisa los datos e intenta de nuevo.'
      });
    }
  };

  const handleEdit = (patient) => {
    const dateObj = formatDateToInput(patient.birthDate || '');
    setEditing(patient.id);
    setForm({
      medicalNumber: patient.medicalNumber,
      firstName: patient.firstName,
      lastName: patient.lastName,
      birthDate: patient.birthDate || '',
      birthYear: dateObj.year,
      birthMonth: dateObj.month,
      birthDay: dateObj.day,
      phone: patient.phone,
      address: patient.address || '',
      city: patient.city || ''
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Estás seguro?')) {
      try {
        await deletePatient(id);
        fetchPatients();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  return (
    <div className="page">
      <div className="page-header">
        <h2>👥 Gestión de Pacientes</h2>
        <button onClick={() => { resetForm(); setShowForm(!showForm); }} className="btn-primary">
          {showForm ? 'Cancelar' : editing ? 'Editar Paciente' : '+ Nuevo Paciente'}
        </button>
      </div>

      <div className="search-bar">
        <input
          type="text"
          placeholder="Buscar paciente..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
        />
        <button type="button" onClick={handleSearch}>Buscar</button>
      </div>

      {schedulingPatient && (
        <div className="schedule-panel">
          <div className="page-header" style={{ alignItems: 'flex-start' }}>
            <div>
              <h2>Agendar cita para {schedulingPatient.firstName} {schedulingPatient.lastName}</h2>
              <p style={{ marginTop: '6px', color: '#526a85' }}>Selecciona la categoría y un profesional para esta cita.</p>
            </div>
            <button type="button" className="btn-danger" onClick={cancelScheduling}>Cerrar</button>
          </div>

          <div className="category-filters">
            {professionalCategories.map((category) => (
              <button
                key={category.value}
                type="button"
                className={`calendar-category ${categoryFilter === category.value ? 'selected' : ''}`}
                onClick={() => setCategoryFilter(category.value)}
              >
                {category.label}
              </button>
            ))}
          </div>

          {filteredProfessionals.length > 0 ? (
            <div className="professional-list">
              {filteredProfessionals.map((professional) => (
                <button
                  key={professional.id}
                  type="button"
                  className={`professional-card ${appointmentForm.professionalId === professional.id ? 'selected' : ''}`}
                  onClick={() => setAppointmentForm({ ...appointmentForm, professionalId: professional.id })}
                >
                  <strong>{professional.firstName} {professional.lastName}</strong>
                  <span>{professional.role ? professional.role.charAt(0).toUpperCase() + professional.role.slice(1) : 'Profesional'}</span>
                  <small>{professional.email || professional.phone || 'Sin contacto'}</small>
                </button>
              ))}
            </div>
          ) : (
            <div className="calendar-empty">No hay profesionales registrados para esta categoría.</div>
          )}

          {selectedProfessional && (
            <div className="professional-selected-summary">
              Profesional seleccionado: <strong>{selectedProfessional.firstName} {selectedProfessional.lastName}</strong> ({selectedProfessional.role})
            </div>
          )}

          <form onSubmit={handleAppointmentSubmit} className="form-container" style={{ marginTop: '20px' }}>
            <input
              type="date"
              value={appointmentForm.appointmentDate}
              onChange={(e) => setAppointmentForm({ ...appointmentForm, appointmentDate: e.target.value })}
              required
            />
            <input
              type="time"
              value={appointmentForm.appointmentTime}
              onChange={(e) => setAppointmentForm({ ...appointmentForm, appointmentTime: e.target.value })}
              required
            />
            <input
              type="text"
              placeholder="Motivo de la cita"
              value={appointmentForm.reason}
              onChange={(e) => setAppointmentForm({ ...appointmentForm, reason: e.target.value })}
              required
            />
            <button type="submit" className="btn-success" disabled={!appointmentForm.professionalId}>Crear cita</button>
          </form>
        </div>
      )}

      {statusMessage.text && (
        <div className={`status-message ${statusMessage.type}`}>
          {statusMessage.text}
        </div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <input
            type="text"
            placeholder="RUT profesional"
            inputMode="numeric"
            maxLength={12}
            value={form.medicalNumber}
            onChange={(e) => setForm({ ...form, medicalNumber: formatMedicalNumberInput(e.target.value) })}
            required
          />
          <input
            type="text"
            placeholder="Nombre"
            value={form.firstName}
            onChange={(e) => setForm({ ...form, firstName: e.target.value })}
            required
          />
          <input
            type="text"
            placeholder="Apellido"
            value={form.lastName}
            onChange={(e) => setForm({ ...form, lastName: e.target.value })}
            required
          />
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr 1fr',
            gap: '10px',
            marginBottom: '15px'
          }}>
            <div>
              <label style={{ fontSize: '12px', color: '#666', display: 'block', marginBottom: '5px' }}>Año</label>
              <input
                type="number"
                placeholder="AAAA"
                min="1900"
                max={new Date().getFullYear()}
                value={form.birthYear}
                onChange={(e) => setForm({ ...form, birthYear: e.target.value })}
                required
                style={{ width: '100%' }}
              />
            </div>
            <div>
              <label style={{ fontSize: '12px', color: '#666', display: 'block', marginBottom: '5px' }}>Mes</label>
              <select
                value={form.birthMonth}
                onChange={(e) => setForm({ ...form, birthMonth: e.target.value })}
                required
                style={{ width: '100%', padding: '8px' }}
              >
                <option value="">Seleccionar mes</option>
                <option value="01">Enero</option>
                <option value="02">Febrero</option>
                <option value="03">Marzo</option>
                <option value="04">Abril</option>
                <option value="05">Mayo</option>
                <option value="06">Junio</option>
                <option value="07">Julio</option>
                <option value="08">Agosto</option>
                <option value="09">Septiembre</option>
                <option value="10">Octubre</option>
                <option value="11">Noviembre</option>
                <option value="12">Diciembre</option>
              </select>
            </div>
            <div>
              <label style={{ fontSize: '12px', color: '#666', display: 'block', marginBottom: '5px' }}>Día</label>
              <input
                type="number"
                placeholder="DD"
                min="1"
                max="31"
                value={form.birthDay}
                onChange={(e) => setForm({ ...form, birthDay: e.target.value })}
                required
                style={{ width: '100%' }}
              />
            </div>
          </div>
          <input
            type="tel"
            placeholder="Teléfono (9 dígitos)"
            inputMode="numeric"
            maxLength={9}
            value={form.phone}
            onChange={(e) => setForm({ ...form, phone: formatPhoneInput(e.target.value) })}
            required
          />
          <input
            type="text"
            placeholder="Dirección"
            value={form.address}
            onChange={(e) => setForm({ ...form, address: e.target.value })}
          />
          <input
            type="text"
            placeholder="Ciudad"
            value={form.city}
            onChange={(e) => setForm({ ...form, city: e.target.value })}
          />
          <button type="submit" className="btn-success">{editing ? 'Actualizar' : 'Guardar'}</button>
        </form>
      )}

      <table className="table">
        <thead>
          <tr>
            <th>Número</th>
            <th>Nombre</th>
            <th>Apellido</th>
            <th>Fecha Nacimiento</th>
            <th>Teléfono</th>
            <th>Ciudad</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {patients.map((p) => (
            <tr key={p.id}>
              <td>{p.medicalNumber}</td>
              <td>{p.firstName}</td>
              <td>{p.lastName}</td>
              <td>{formatDate(p.birthDate)}</td>
              <td>{p.phone}</td>
              <td>{p.city}</td>
              <td>
                <button className="btn-secondary" onClick={() => startScheduling(p)}>Agendar</button>
              <button className="btn-primary" onClick={() => handleEdit(p)}>Editar</button>
              <button className="btn-danger" onClick={() => handleDelete(p.id)}>Eliminar</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
